const rawAnimals = $('Fetch Animals').first().json;
const animalsArr = Array.isArray(rawAnimals) ? rawAnimals : [];

const rawWeights = $('Fetch Weight Logs').first().json;
const weightsArr = Array.isArray(rawWeights) ? rawWeights : [];

const rawHealth = $input.first().json;
const healthArr = Array.isArray(rawHealth) ? rawHealth : [];

const totalAnimals = animalsArr.length;
const byCattle  = animalsArr.filter(a => (a.type || '').toLowerCase() === 'cattle').length;
const bySwine   = animalsArr.filter(a => (a.type || '').toLowerCase() === 'swine').length;
const byPoultry = animalsArr.filter(a => (a.type || '').toLowerCase() === 'poultry').length;

const withWeight = weightsArr.filter(w => w.weight_kg > 0);
const avgWeight = withWeight.length > 0
  ? (withWeight.reduce((s, w) => s + parseFloat(w.weight_kg), 0) / withWeight.length).toFixed(1)
  : null;
const maxWeight = withWeight.length > 0
  ? Math.max(...withWeight.map(w => parseFloat(w.weight_kg))).toFixed(1)
  : null;
const minWeight = withWeight.length > 0
  ? Math.min(...withWeight.map(w => parseFloat(w.weight_kg))).toFixed(1)
  : null;

const recentAlerts = healthArr.slice(0, 3).map(r => ({
  animal_id: r.animal_id,
  symptoms: (r.symptoms_description || '').substring(0, 90),
  date: r.recorded_at ? r.recorded_at.split('T')[0] : 'N/A'
}));

const has_data = totalAnimals > 0;
const model = $env.DEEPSEEK_MODEL || 'deepseek-chat';

const systemPrompt = 'You are AURA, FincApp farm operations assistant. Return ONLY valid JSON in English. One sentence recommendation.';
const userPrompt = 'Weekly farm: ' + totalAnimals + ' animals (' + byCattle + ' cattle, ' + bySwine + ' swine, ' + byPoultry + ' poultry). Weight logs: ' + withWeight.length + ' entries, avg ' + (avgWeight || 'no data') + ' kg. Recent health records: ' + healthArr.length + '. Return JSON: recommendation (one sentence), priority (low/medium/high), safe_wording (if health risk else null).';

return [{
  json: {
    has_data, totalAnimals, byCattle, bySwine, byPoultry,
    avgWeight, maxWeight, minWeight, weightEntries: withWeight.length,
    totalHealthRecords: healthArr.length, recentAlerts,
    report_date: new Date().toISOString().split('T')[0],
    llm_model: model, prompt_system: systemPrompt, prompt_user: userPrompt
  }
}];

const d = $('Compile Report Data').first().json;
const llmRaw = $input.first().json;

const fallbackRec = { recommendation: 'Keep monitoring your animals daily and log all health events so AURA can detect patterns early.', priority: 'low', safe_wording: null };
let rec = fallbackRec;
try {
  const parsed = JSON.parse(llmRaw.choices[0].message.content);
  if (parsed.recommendation) rec = parsed;
} catch (e) {}

const noData = '<span style="color:#999;font-style:italic">No data available</span>';
const pColor = { low: '#27ae60', medium: '#f39c12', high: '#e74c3c' }[rec.priority] || '#666';
const tdS = 'padding:8px 12px;border-bottom:1px solid #eee;';
const thS = 'background:#1a1a2e;color:#2ecc71;padding:10px 12px;text-align:left;font-size:13px;';

const inv = d.has_data
  ? '<tr><td style="' + tdS + '">Total Animals</td><td style="' + tdS + '"><strong>' + d.totalAnimals + '</strong></td></tr>' +
    '<tr><td style="' + tdS + '">Cattle</td><td style="' + tdS + '">' + d.byCattle + '</td></tr>' +
    '<tr><td style="' + tdS + '">Swine</td><td style="' + tdS + '">' + d.bySwine + '</td></tr>' +
    '<tr><td style="' + tdS + '">Poultry</td><td style="' + tdS + '">' + d.byPoultry + '</td></tr>'
  : '<tr><td colspan="2" style="' + tdS + '">' + noData + '</td></tr>';

const wgt = d.avgWeight
  ? '<tr><td style="' + tdS + '">Average Weight</td><td style="' + tdS + '"><strong>' + d.avgWeight + ' kg</strong></td></tr>' +
    '<tr><td style="' + tdS + '">Max Weight</td><td style="' + tdS + '">' + d.maxWeight + ' kg</td></tr>' +
    '<tr><td style="' + tdS + '">Min Weight</td><td style="' + tdS + '">' + d.minWeight + ' kg</td></tr>' +
    '<tr><td style="' + tdS + '">Log Entries</td><td style="' + tdS + '">' + d.weightEntries + '</td></tr>'
  : '<tr><td colspan="2" style="' + tdS + '">' + noData + '</td></tr>';

const hlth = d.totalHealthRecords > 0
  ? '<tr><td style="' + tdS + '">Total Records</td><td style="' + tdS + '">' + d.totalHealthRecords + '</td></tr>' +
    d.recentAlerts.map(a =>
      '<tr><td style="' + tdS + 'font-size:12px;color:#555;">Animal ' + a.animal_id.substring(0,8) + '... — ' + a.date + '</td>' +
      '<td style="' + tdS + 'font-size:12px;color:#555;">' + a.symptoms + '</td></tr>'
    ).join('')
  : '<tr><td colspan="2" style="' + tdS + '">' + noData + '</td></tr>';

const safeBlock = rec.safe_wording
  ? '<p style="background:#fff3cd;border-left:4px solid #f39c12;padding:10px;margin-top:12px;font-size:13px;">⚠️ ' + rec.safe_wording + '</p>'
  : '';

const section = (title) => '<h2 style="color:#1a1a2e;border-bottom:2px solid #2ecc71;padding-bottom:6px;margin-top:24px;">' + title + '</h2>';
const table = (rows) => '<table width="100%" cellpadding="0" cellspacing="0"><thead><tr><th style="' + thS + '">Metric</th><th style="' + thS + '">Value</th></tr></thead><tbody>' + rows + '</tbody></table>';

const html = '<!DOCTYPE html><html><body style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;color:#333;">' +
  '<div style="background:#1a1a2e;padding:20px;text-align:center;">' +
  '<h1 style="color:#2ecc71;margin:0;">AURA</h1>' +
  '<p style="color:#aaa;margin:4px 0 0;">FincApp Weekly Farm Summary — ' + d.report_date + '</p></div>' +
  '<div style="padding:20px;">' +
  section('Inventory') + table(inv) +
  section('Weight Metrics') + table(wgt) +
  section('Health Records') + table(hlth) +
  section('AURA Recommendation') +
  '<div style="background:#f8f9fa;border-radius:8px;padding:16px;">' +
  '<span style="background:' + pColor + ';color:#fff;padding:3px 10px;border-radius:12px;font-size:12px;font-weight:bold;">' + rec.priority.toUpperCase() + '</span>' +
  '<p style="margin:10px 0 0;">' + rec.recommendation + '</p>' + safeBlock + '</div>' +
  '</div><div style="background:#f1f1f1;padding:12px;text-align:center;font-size:11px;color:#999;">' +
  'FincApp · AURA does not replace professional veterinary advice · ' + d.report_date + '</div>' +
  '</body></html>';

return [{ json: { html, subject: 'FincApp Weekly Farm Summary — ' + d.report_date } }];
